const input = $input.first().json;
const event = input.event || input;
const context = input.context || {};
const order = context.order || {};
const customer = context.customer || {};
const reason = context.returnReason || context.rawPayload?.reason || 'not_provided';
const returnHistoryCount = (context.rawPayload?.returnHistory || []).length || customer.returnCount || 0;

return [{
  json: {
    event,
    context,
    order,
    customer,
    reason,
    returnHistoryCount,
    orderValue: order.value || context.rawPayload?.orderValue || 0,
    productId: event.productId || context.product?.id || '',
    daysSincePurchase: context.rawPayload?.daysSincePurchase || null
  }
}];

