const item = $input.first().json;
let text = item.text || item.output || JSON.stringify(item);
text = String(text).replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    risk: 'MEDIUM_RISK',
    decision: 'HUMAN_REVIEW',
    reason: 'AI parse failed',
    confidence: 0.1,
    action: 'HUMAN_REVIEW',
    channel: 'slack',
    message: '',
    escalate: true,
    priority: 'medium',
    productQualitySignal: false
  };
}

const upstream = $('Prepare Return Context').first().json;
const allowed = ['AUTO_APPROVE','HUMAN_REVIEW','REQUEST_INFORMATION','ESCALATE'];
if (!allowed.includes(parsed.decision)) {
  parsed.decision = 'HUMAN_REVIEW';
  parsed.escalate = true;
}
// Safety: never auto-deny
if (parsed.decision === 'DENY' || parsed.decision === 'AUTO_DENY') {
  parsed.decision = 'HUMAN_REVIEW';
  parsed.escalate = true;
}

return [{
  json: {
    agent: 'returns_intelligence',
    decision: parsed.decision,
    reason: parsed.reason || '',
    confidence: Number(parsed.confidence) || 0,
    action: parsed.action || parsed.decision,
    channel: parsed.channel || 'slack',
    message: parsed.message || '',
    escalate: !!parsed.escalate || parsed.decision !== 'AUTO_APPROVE',
    priority: parsed.priority || 'medium',
    risk: parsed.risk || 'MEDIUM_RISK',
    productQualitySignal: !!parsed.productQualitySignal,
    customerId: upstream.event?.customerId || '',
    orderId: upstream.event?.orderId || '',
    status: 'decided'
  }
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    status: d.decision === 'AUTO_APPROVE' ? 'auto_approved' : (d.escalate ? 'escalated' : 'reviewed')
  }
}];
